script:
// Generátor – forgó tekercs homogén mágneses térben
// Generator – a coil turning in a uniform magnetic field
//   u = N·B·A·ω·cos θ        kommutátorral / with commutator: |u|

// Vászon: szélesség, magasság (px), háttérszín / Canvas: width, height (px), background colour
stage(1000, 600, "#fbfbf8");
// Felirat a vászon bal felső sarkában / Caption in the top-left corner
title({hu: "Generátor", en: "Generator"});
// Kezdő lassítás (a Sebesség csúszkán állítható) / Initial slow motion (change it on the Speed slider)
timeScale(0.025);
// A grafikon időablaka másodpercben / Chart time window in seconds
plotWindow(3);

// Csúszkák: azonosító, felirat (HU/EN), min, max, alapérték, lépés, egység – értékük: P.azonosító / Sliders: id, label (HU/EN), min, max, default, step, unit – value: P.id
param("n",  {hu: "Fordulatszám n", en: "Speed n"}, 0, 600, 120, 1, "1/min");
param("N",  {hu: "Menetszám N", en: "Number of turns N"}, 1, 300, 100, 1, "");
param("B",  {hu: "Mágneses indukció B", en: "Flux density B"}, 0, 1.5, 0.8, 0.01, "T");
param("A",  {hu: "Tekercs felülete A", en: "Coil area A"}, 5, 100, 40, 1, "cm²");
param("RL", {hu: "Terhelés (izzó) R", en: "Load (lamp) R"}, 1, 100, 10, 1, "Ω");
// Kapcsolók: értékük true / false / Switches: their value is true / false
toggle("comm",  {hu: "Kommutátor (egyenirányítás)", en: "Commutator (rectified)"}, false);
toggle("field", {hu: "Erővonalak", en: "Field lines"}, true);

let theta = 0, u = 0, i = 0;

// Fizika: sok kis lépésben fut, dt a lépés hossza (s) / Physics: runs in many small steps, dt is the step length (s)
update(dt => {
  const w = P.n * PI / 30;
  theta += w * dt;
  const k = P.N * P.B * P.A * 1e-4;
  // Indukált feszültség: u = N·B·A·ω·cos θ / induced voltage
  const ui = k * w * cos(theta);   // a tekercsben indukált / induced in the coil
  u = P.comm ? abs(ui) : ui;
  // Ohm törvénye a terhelésen / Ohm’s law on the load
  i = u / P.RL;
});

const cx = 360, cy = 320, r = 120;

// Rajzolás minden képkockán (szünetben is) / Drawing on every frame (also while paused)
draw(t => {
  rect(62, 100, 596, 440, {stroke: "#9aa3b1", lw: 16, radius: 28});
  rect(70, 170, 120, 300, {fill: C.N, radius: 4});
  rect(530, 170, 120, 300, {fill: C.S, radius: 4});
  text("N", 130, 320, {size: 46, bold: true, color: "#fff", align: "center", baseline: "middle"});
  text("S", 590, 320, {size: 46, bold: true, color: "#fff", align: "center", baseline: "middle"});
  if (P.field && P.B > 0.001) {
    const n = round(3 + P.B / 1.5 * 9);
    for (let j = 0; j < n; j++) {
      const y = 182 + (j + 0.5) * 276 / n;
      line(190, y, 530, y, {stroke: "#8b95a5", lw: 1.2, alpha: 0.6});
      arrow(196, y, 228, y, {stroke: "#8b95a5", lw: 1.2, head: 7, id: "erővonal-nyíl"});
      arrow(492, y, 524, y, {stroke: "#8b95a5", lw: 1.2, head: 7, id: "erővonal-nyíl"});
    }
  }

  circle(cx, cy, r, {fill: "rgba(255,255,255,0.55)", stroke: "#c3cad5", lw: 2, dash: [6, 6]});
  const ax = cx + r * cos(theta), ay = cy - r * sin(theta);
  const bx = cx - r * cos(theta), by = cy + r * sin(theta);
  line(ax, ay, bx, by, {stroke: C.copper, lw: 6, alpha: 0.85});
  circle(cx, cy, 11, {fill: C.ink});

  // A vezetők sebessége és az indukált áram iránya (v × B)
  // Conductor velocity and induced current direction (v × B)
  const turning = P.n > 0 ? 1 : 0;
  if (turning) {
    vector(ax, ay, -sin(theta) * 48, -cos(theta) * 48, {stroke: C.green, lw: 2.5}, "v");
    vector(bx, by, sin(theta) * 48, cos(theta) * 48, {stroke: C.green, lw: 2.5}, "v");
  }
  // Áramirány a vezetőkben: ⊙ kifelé, ⊗ befelé / current direction: ⊙ out, ⊗ in
  const dA = -sign(cos(theta)) * turning;
  current(ax, ay, dA, 17, {stroke: C.orange, lw: 3});
  current(bx, by, -dA, 17, {stroke: C.teal, lw: 3});

  // Izzó / lamp
  const lx = 830, ly = 190;
  const pw = u * i;
  // Az izzó fényereje a teljesítménnyel nő / lamp brightness grows with power
  const glow = clamp(pw / 3, 0, 1);
  if (glow > 0.01) circle(lx, ly, 46 + 50 * glow, {fill: C.yellow, alpha: 0.3 * glow, stroke: false});
  circle(lx, ly, 42, {fill: glow > 0.01 ? "rgba(255, 205, 60, " + (0.25 + 0.75 * glow) + ")" : "#ffffff", stroke: C.ink, lw: 2});
  polyline([[lx - 14, ly + 40], [lx - 10, ly + 2], [lx - 5, ly - 8], [lx, ly + 2], [lx + 5, ly - 8], [lx + 10, ly + 2], [lx + 14, ly + 40]], {stroke: "#6b4a10", lw: 1.6});
  rect(lx - 20, ly + 38, 40, 28, {fill: "#9aa3b1", radius: 3});

  // Gyűjtő: csúszógyűrűk vagy kommutátor / collector: slip rings or commutator
  const kx = 830, ky = 440, kr = 40;
  polyline([[lx - 10, ly + 66], [lx - 10, 330], [kx - 90, 330], [kx - 90, ky], [kx - kr - 30, ky]], {stroke: C.ink, lw: 2});
  polyline([[lx + 10, ly + 66], [lx + 10, 330], [kx + 90, 330], [kx + 90, ky], [kx + kr + 30, ky]], {stroke: C.ink, lw: 2});
  rect(kx - kr - 30, ky - 12, 22, 24, {fill: "#5b6472", radius: 3});
  rect(kx + kr + 8, ky - 12, 22, 24, {fill: "#5b6472", radius: 3});
  if (P.comm) {
    arc(kx, ky, kr, -theta - PI / 2 + 0.2, -theta + PI / 2 - 0.2, {stroke: C.orange, lw: 14});
    arc(kx, ky, kr, -theta + PI / 2 + 0.2, -theta + 3 * PI / 2 - 0.2, {stroke: C.teal, lw: 14});
  } else {
    circle(kx, ky, kr, {stroke: C.copper, lw: 14});
    circle(kx + kr * cos(-theta), ky + kr * sin(-theta), 4, {fill: "#fff"});
  }
  circle(kx, ky, 8, {fill: C.ink});
  text(P.comm ? {hu: "kommutátor → lüktető egyenfeszültség", en: "commutator → pulsating DC"}
              : {hu: "csúszógyűrű → váltakozó feszültség", en: "slip ring → alternating voltage"},
       kx, ky + kr + 40, {size: 14, color: C.gray, align: "center"});

  const w = P.n * PI / 30, k = P.N * P.B * P.A * 1e-4, Umax = k * w;
  // Mért értékek a Vezérlők fülön / Readouts on the Controls tab
  show({hu: "Pillanatnyi feszültség u", en: "Instantaneous voltage u"}, u, "V");
  show({hu: "Áram i", en: "Current i"}, i, "A");
  show({hu: "Csúcsfeszültség Û = N·B·A·ω", en: "Peak voltage Û = N·B·A·ω"}, Umax, "V");
  if (P.comm) show({hu: "Középérték 2Û/π", en: "Average value 2Û/π"}, 2 * Umax / PI, "V");
  else show({hu: "Effektív érték Û/√2", en: "RMS value Û/√2"}, Umax / sqrt(2), "V");
  show({hu: "Frekvencia f = n/60", en: "Frequency f = n/60"}, P.n / 60, "Hz");
  show({hu: "Pillanatnyi teljesítmény", en: "Instantaneous power"}, pw, "W");

  // Élő grafikonok a vászon alatt / Live charts under the canvas
  plot({hu: "Feszültség u", en: "Voltage u"}, u, {unit: "V", color: C.blue});
  plot({hu: "Áram i", en: "Current i"}, i, {unit: "A", color: C.orange});
});
